<script setup lang="ts">
import {setSubscriptionRegions} from '../lib'
import {ref,onMounted,watch} from 'vue'
import TierEditor from './TierEditor.vue'
import BillingEditor from './BillingEditor.vue'
import SiteIconUpload from './SiteIconUpload.vue'
import {Save,Settings2} from 'lucide-vue-next'
import {api,notify,subscriptionRegions,regionLabel,type Row} from '../lib'
const props=defineProps<{group:string;value:Row}>();const emit=defineEmits<{saved:[]}>();const form=ref<Row>(JSON.parse(JSON.stringify(props.value))),busy=ref(false),err=ref('')
const jsonText=ref(JSON.stringify(props.value.address_templates||props.value.items||[],null,2))
const proxies=ref<Row[]>([]),iconReading=ref(false)
if(props.group==='site')form.value.sidebar_default_expanded??=false
if(props.group==='proxy')form.value.global_id??=''
const checkoutPlans=[{id:'pro5x',name:'Pro 5x',default:'hosted'},{id:'pro',name:'Pro 20x',default:'hosted'},{id:'team',name:'Team团队订阅',default:'oaics'},{id:'team_premium',name:'Team 高级',default:'oaics'},{id:'plus',name:'Plus',default:'oaics',preset:true},{id:'go',name:'Go',default:'oaics',preset:true},{id:'promax',name:'Pro 50x（Pro Max）',default:'hosted',flow:'cslive_go_direct_pay'}]
if(props.group==='payment'){delete form.value.checkout_flow;form.value.network_restart_limit??=2;form.value.post_payment_delay_seconds??=5;form.value.cslive_go_visit_return??=true;form.value.cslive_go_refresh_before_renewal??=true;form.value.post_refresh_retries??=4;form.value.post_refresh_interval_seconds??=3;if(!['gener_direct_pay','cslive_go_direct_pay','cslive_full_go'].includes(form.value.subscription_flow))form.value.subscription_flow='';form.value.checkout_type??='hosted';form.value.checkout_types={...Object.fromEntries(checkoutPlans.map(p=>[p.id,p.default])),...form.value.checkout_types}}
if(props.group==='payment')watch(()=>form.value.subscription_flow,flow=>{if(flow==='gener_direct_pay'){form.value.checkout_type='hosted';form.value.checkout_types=Object.fromEntries(checkoutPlans.map(p=>[p.id,'hosted']))}},{immediate:true})
if(props.group==='scheduler')form.value.link_mode='long'
onMounted(async()=>{if(props.group==='scheduler'){try{const rows=(await api('/admin/regions')).items.filter((r:Row)=>r.enabled);setSubscriptionRegions(rows);const field=fields.scheduler.find(f=>f.k==='default_country');if(field)field.options=rows.map((r:Row)=>r.code)}catch(e){err.value=(e as Error).message}}if(props.group==='proxy')try{proxies.value=(await api('/admin/resources')).items}catch(e){err.value=(e as Error).message}})
const fields:Record<string,Row[]>={
 payment:[{k:'post_payment_delay_seconds',n:'付款成功后等待（秒）',min:0,max:300},{k:'network_restart_limit',n:'付款前网络重试次数',min:0,max:5},{k:'activation_check_interval_seconds',n:'付款后订阅生效核实间隔（秒）',min:2,max:300},{k:'activation_check_limit',n:'订阅生效最多核实次数',min:1,max:120},{k:'subscription_wait_seconds',n:'订阅准备最长等待（秒）',min:30,max:1800},{k:'renewal_check_interval_seconds',n:'关闭续费核实间隔（秒）',min:5,max:300},{k:'renewal_check_limit',n:'关闭续费最多核实次数',min:1,max:60},{k:'enabled',n:'开放站内付款',type:'switch'},{k:'max_parallel',n:'付款任务总并发',min:1,max:20},{k:'per_user_parallel',n:'单客户付款并发',min:1,max:5},{k:'prepare_timeout_seconds',n:'报价准备超时（秒）',min:30,max:300},{k:'quote_timeout_seconds',n:'等待客户确认（秒）',min:30,max:600},{k:'result_timeout_seconds',n:'付款结果等待（秒）',min:30,max:600},{k:'requests_per_minute',n:'每客户每分钟准备次数',min:1,max:20},{k:'post_refresh_retries',n:'付款后会话刷新重试次数',min:1,max:10},{k:'post_refresh_interval_seconds',n:'付款后会话刷新重试间隔（秒）',min:1,max:30}],
 proxy:[{k:'request_timeout_seconds',n:'每次上游请求超时（秒）',min:10,max:120}],
 risk:[{k:'login_per_minute',n:'每 IP 每分钟登录次数',min:1,max:100},{k:'api_per_minute',n:'每账号每分钟接口请求',min:10,max:10000},{k:'order_per_minute',n:'每账号每分钟创建订单',min:1,max:100},{k:'max_open_orders',n:'每账号未完成订单上限',min:1,max:500},{k:'max_topup',n:'单笔充值上限（积分）',min:1,max:1000000,money:true},{k:'session_hours',n:'登录有效期（小时）',min:1,max:168},{k:'event_retention_days',n:'风控事件保留天数',min:7,max:365}],
 scheduler:[{k:'paused',n:'暂停队列领取',type:'switch'},{k:'max_parallel',n:'全局最大并发',min:1,max:100},{k:'per_user_parallel',n:'单账号最大并发',min:1,max:20},{k:'retry_limit',n:'安全失败最大重试次数',min:0,max:10},{k:'retry_delay_seconds',n:'重试间隔（秒）',min:5,max:3600},{k:'task_timeout_seconds',n:'任务超时（秒）',min:30,max:1800},{k:'queue_limit',n:'等待队列上限',min:1,max:10000},{k:'default_country',n:'默认订阅地区',type:'select',options:subscriptionRegions.map(r=>r.code)}],
 site:[{k:'name',n:'中文品牌',type:'text'},{k:'english_name',n:'英文名称',type:'text'},{k:'tagline',n:'品牌说明',type:'text'},{k:'terms',n:'服务约定',type:'textarea'}],
 billing:[{k:'country',n:'默认付款账单国家',type:'fixed'}]
}
for(const f of fields[props.group]||[])if(f.money)form.value[f.k]/=100
async function save(){if(busy.value||iconReading.value)return;busy.value=true;err.value='';try{const payload=JSON.parse(JSON.stringify(form.value));for(const f of fields[props.group]||[])if(f.money)payload[f.k]=Math.round(payload[f.k]*100);if(props.group==='proxy')payload.match_country=true;if(props.group==='tiers')payload.items=JSON.parse(jsonText.value);await api('/admin/settings/'+props.group,'PUT',payload);notify('配置已保存');emit('saved')}catch(e){err.value=(e as Error).message}finally{busy.value=false}}
</script>
<template><TierEditor v-if="group==='tiers'" :value="value" @saved="emit('saved')"/><BillingEditor v-else-if="group==='billing'" :value="value"/><form v-else @submit.prevent="save"><div class="alert danger" v-if="err">{{err}}</div><SiteIconUpload v-if="group==='site'" v-model="form.icon" :name="form.name" :disabled="busy" @busy="iconReading=$event"/><div class="callout" v-if="group==='scheduler'">结账准备按队列、并发与重试间隔执行；上游创建结果不明时停止重发。付款并发及超时在付款配置中设置。</div><template v-if="group==='payment'"><div class="callout">网络重试次数不含首次执行，0 为关闭，默认 2 次。间隔使用资源调度中的“重试间隔”。提链成功后复用原链接从付款阶段重试；已付款成功或付款结果不明时停止自动重付。</div><div class="callout">“+Go付款成功后续”流程在付款成功后先等待，再强制刷新 Session。默认等待 5 秒，设为 0 则立即刷新；刷新失败后的重试次数和间隔由下方对应设置控制。</div><label>订阅办理流程<select v-model="form.subscription_flow" aria-label="订阅办理流程" required><option v-if="!form.subscription_flow" value="" disabled>请选择订阅办理流程</option><option value="gener_direct_pay">gener提链+http直连付款流程 +Go付款成功后续</option><option value="cslive_go_direct_pay">Go提链+http直连付款流程 +Go付款成功后续</option><option value="cslive_full_go">完整cslive流程（Go 提链+付款+续费一体）</option></select></label><section v-if="form.subscription_flow==='cslive_go_direct_pay'" class="callout"><h3>付款成功后的可选步骤</h3><label>访问付款回跳页<input class="toggle" type="checkbox" v-model="form.cslive_go_visit_return"/></label><label>取消自动续费前强制刷新 Session<input class="toggle" type="checkbox" v-model="form.cslive_go_refresh_before_renewal"/></label><small>仅作用于当前 Go 提链 + HTTP 直连付款流程。关闭第二项后使用本单最新凭据；付款后的首次刷新和订阅核实遇 401 刷新仍然保留。</small></section><section class="checkout-plan-settings"><h3>套餐结账链接</h3><p class="muted">{{form.subscription_flow==='gener_direct_pay'?'gener 流程所有套餐固定使用长链。':'由管理员逐项选择套餐的长链或短链。'}}</p><div class="form-grid"><label v-for="plan in checkoutPlans.filter(p=>(!p.flow||p.flow===form.subscription_flow)&&!(p.id==='team_premium'&&form.subscription_flow==='cslive_go_direct_pay'))" :key="plan.id">{{plan.name}}<select v-model="form.checkout_types[plan.id]" :aria-label="plan.name+' 结账链接类型'" :disabled="form.subscription_flow==='gener_direct_pay'"><option value="hosted">长链</option><option value="oaics">短链</option></select><small v-if="plan.preset && !(plan.id==='plus' && form.subscription_flow==='cslive_go_direct_pay')">预设规则，当前尚未上架</small></label></div><p class="muted">{{form.subscription_flow==='gener_direct_pay'?'保存时全部套餐统一为长链。':'长短链按套餐单独保存。'}}</p></section></template><template v-if="group==='proxy'"><div class="callout">按订单的订阅地区自动匹配代理。同地区没有空闲代理时排队；同一轮任务固定使用同一代理，所有提链请求均经该代理执行。</div><label>续费全局代理<select v-model="form.global_id"><option value="">未配置（续费任务等待）</option><option v-for="p in proxies" :key="p.id" :value="p.id" :disabled="!p.enabled">{{p.name}} · {{regionLabel(p.country)}}{{p.enabled?'':'（停用）'}}</option></select><small>仅用于续费管理菜单发起的取消和前后查询，不受订阅地区限制。订阅办理中的后续步骤沿用原订单代理。</small></label><label>同地区优先代理<select v-model="form.default_id"><option value="">按订阅地区自动分配</option><option v-for="p in proxies" :key="p.id" :value="p.id" :disabled="!p.enabled">{{p.name}} · {{regionLabel(p.country)}}{{p.enabled?'':'（停用）'}}</option></select><small>仅在订阅地区相同时优先使用；停用或占满时自动选择同地区其他代理，不跨地区分配。</small></label></template><div class="form-grid"><label v-for="f in fields[group]||[]" :key="f.k" :class="{span2:f.type==='textarea'}">{{f.n}}<input v-if="f.type==='switch'" class="toggle" type="checkbox" v-model="form[f.k]"/><textarea v-else-if="f.type==='textarea'" v-model="form[f.k]" rows="5" required></textarea><select v-else-if="f.type==='select'" v-model="form[f.k]"><option v-for="o in f.options" :key="o" :value="o">{{f.k==='default_country'?regionLabel(o):o}}</option></select><input v-else-if="f.type==='text'||f.type==='fixed'" v-model="form[f.k]" :readonly="f.type==='fixed'" required maxlength="500"/><input v-else v-model.number="form[f.k]" type="number" :min="f.min" :max="f.max" :step="f.money?'0.01':'1'" required/></label></div><template v-if="group==='tiers'"><p>按累计充值门槛使用对应折扣，账户专属单价优先。金额门槛单位为分；discount 为原价百分比。</p><label>等级列表<textarea class="mono" v-model="jsonText" rows="12" spellcheck="false"></textarea></label></template><p v-if="group==='site'" class="callout">客服账号与 TG 群组请在<a href="#/admin/support" class="text-btn">联系客服</a>中统一配置。</p><section v-if="group==='site'" class="navigation-settings"><h3>界面与导航</h3><label>用户端二级菜单默认状态<select v-model="form.sidebar_default_expanded" aria-label="用户端二级菜单默认状态"><option :value="false">默认收起</option><option :value="true">默认展开</option></select></label><p class="muted small">控制注册办理、订阅办理下的二级菜单。用户仍可点击箭头展开或收起；直接进入子页面时，会展开对应分组。</p></section><div class="form-footer"><button class="btn primary" :disabled="busy||iconReading"><Save :size="16"/>{{busy?'保存中…':'保存配置'}}</button></div></form></template>

<style scoped>
.navigation-settings{margin-top:28px;padding-top:24px;border-top:1px solid var(--line)}.navigation-settings h3{font-size:14px;margin:0 0 18px}.navigation-settings label{display:grid;gap:10px;font-size:12px;max-width:360px}.navigation-settings p{line-height:1.8;margin:12px 0 0}
</style>
